#!/usr/bin/env node
/**
 * Pre-build completeness check — the first command in netlify.toml's build.
 *
 * Background: a deploy whose upload was incomplete (a partial extract or sync
 * on the way to the repo) used to surface as two dozen cryptic Turbopack
 * "Module not found" errors minutes into the build. This gate turns that into
 * an immediate, exact list of what is missing, before anything else runs.
 *
 * It compares the tree against .build-manifest.json — the file list the
 * release zip was built from (one path per line), generated by
 * scripts/package-zip.sh. Extra files are fine (it only checks for missing
 * ones).
 */
import { readFileSync, existsSync } from 'node:fs'
import { join, dirname } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = join(dirname(fileURLToPath(import.meta.url)), '..')
const manifestPath = join(root, '.build-manifest.json')

if (!existsSync(manifestPath)) {
  console.error('[FAIL] .build-manifest.json not found - cannot verify the tree.')
  console.error('       Re-extract the complete release zip; it ships in the zip root.')
  process.exit(1)
}

let expected
try {
  // plain format written by package-zip.sh: one path per line, `./`-stripped
  expected = readFileSync(manifestPath, 'utf8')
    .split(/\r?\n/)
    .map((l) => l.trim())
    .filter((l) => l.length > 0)
} catch (e) {
  console.error('[FAIL] .build-manifest.json could not be read:', e.message)
  process.exit(1)
}
if (expected.length === 0) {
  console.error('[FAIL] .build-manifest.json is empty - cannot verify the tree.')
  process.exit(1)
}

const missing = expected.filter((f) => !existsSync(join(root, f)))

if (missing.length > 0) {
  console.error(`[FAIL] Incomplete upload: ${missing.length} of ${expected.length} expected files are missing:`)
  for (const f of missing) console.error(`       - ${f}`)
  console.error('')
  console.error('       The deploy source is incomplete - files were dropped on the way to the repo')
  console.error('       (partial extract / sync of the release zip). Fix: replace the source in your')
  console.error('       repo with a fresh extract of the full zip - do not merge over an old tree -')
  console.error('       commit everything, and push again.')
  process.exit(1)
}

console.log(`[OK] tree complete: all ${expected.length} files from .build-manifest.json present`)
